import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
const source = await readFile(
  new URL('../server/src/contracts/public.ts', import.meta.url),
  'utf8',
);
const outputs = [
  {
    target: new URL('../client/src/shared/api/contracts.generated.ts', import.meta.url),
    value:
      '// Generated by tooling/contracts.ts from server/src/contracts/public.ts. Do not edit.\n' +
      source,
  },
  {
    target: new URL('../server/src/contracts/format.generated.ts', import.meta.url),
    value:
      "// Generated by tooling/contracts.ts. Current data contract; no compatibility adapters.\nexport const contractSignature = '" +
      createHash('sha256').update(source).digest('hex') +
      "';\n",
  },
];
for (const { target, value } of outputs) {
  const previous = await readFile(target, 'utf8').catch(() => '');
  if (previous === value) continue;
  if (process.argv.includes('--check')) {
    console.error('Generated contracts are stale. Run yarn contracts:generate.');
    process.exitCode = 1;
  } else await writeFile(target, value);
}
